package net.civeira.phylax.feature.identity.tenantloginprovider.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.identity.tenantloginprovider.domain.TenantLoginProvider;
import net.civeira.phylax.feature.identity.tenantloginprovider.domain.valueobject.PrivateKeyVO;

class PrivateKeyValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of private key of tenant login provider")
  void test_private_key_value_holder_assign_plain_value() {
    Object holder = new Object();
    PrivateKeyValueHolder<Object> value = new PrivateKeyValueHolder<>(holder);
    Assertions.assertSame(holder, value.privateKey("one"), "Setters must return the holder");
    Assertions.assertTrue(value.getPrivateKeyValue().isPresent(), "The plain value must be stored");
    Assertions.assertEquals("one", value.getPrivateKey().orElse(null),
        "The plain value must be recovered");
    Assertions.assertSame(holder, value.privateKeyNull(), "Setters must return the holder");
    Assertions.assertTrue(value.getPrivateKeyValue().isPresent(),
        "A null value object must be stored");
    Assertions.assertFalse(value.getPrivateKey().isPresent(), "A null value must not have content");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of private key of tenant login provider")
  void test_private_key_value_holder_assign_value_object() {
    Object holder = new Object();
    PrivateKeyValueHolder<Object> value = new PrivateKeyValueHolder<>(holder);
    PrivateKeyVO vo = PrivateKeyVO.from("one");
    Assertions.assertFalse(value.getPrivateKeyValue().isPresent(), "A new holder must be empty");
    Assertions.assertSame(holder, value.privateKey(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getPrivateKeyValue().orElseThrow());
    Assertions.assertSame(holder, value.privateKey(Optional.empty()));
    Assertions.assertFalse(value.getPrivateKeyValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.privateKey(Optional.of(vo)));
    Assertions.assertSame(vo, value.getPrivateKeyValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of private key of tenant login provider against the original")
  void test_private_key_value_holder_read() {
    Object holder = new Object();
    PrivateKeyValueHolder<Object> value = new PrivateKeyValueHolder<>(holder);
    PrivateKeyVO vo = PrivateKeyVO.from("one");
    PrivateKeyVO other = PrivateKeyVO.from("one");
    TenantLoginProvider original = Mockito.mock(TenantLoginProvider.class);
    Mockito.when(original.getPrivateKeyValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readPrivateKey(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNotNull(value.readPrivateKey(Optional.empty(), fails),
        "Without value and original a null value is returned");
    Assertions.assertTrue(fails.isEmpty(), "An optional value is never reported as missing");
    value.privateKey(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readPrivateKey(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readPrivateKey(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of private key of tenant login provider")
  void test_private_key_value_holder_unset() {
    Object holder = new Object();
    PrivateKeyValueHolder<Object> value = new PrivateKeyValueHolder<>(holder);
    PrivateKeyVO vo = PrivateKeyVO.from("one");
    value.privateKey(vo);
    Assertions.assertSame(holder, value.unsetPrivateKeyIfMatches("privateKey_other"));
    Assertions.assertTrue(value.getPrivateKeyValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetPrivateKeyIfMatches("privateKey"));
    Assertions.assertFalse(value.getPrivateKeyValue().isPresent(),
        "The field name must clear the value");
    value.privateKey(vo);
    Assertions.assertSame(holder, value.unsetPrivateKey());
    Assertions.assertFalse(value.getPrivateKeyValue().isPresent(), "Unset must clear the value");
  }
}
